mapper.select:
select r.rule_id as ruleId,count(p.id) as count,r.rule_name as ruleName,r.remark from promotion_rule r left join med_exam_package p on r.rule_id = p.promotion_id
and r.rule_name like concat('%', #{ruleName}, '%')
group by r.rule_id order by r.rule_id asc limit #{startIndex}, #{pageSize}

mapper.update:
update promotion_rule set
                          rule_name = #{ruleName},
                          rule_content = #{ruleContent},
                          remark = #{remark}
where
    rule_id = #{ruleId}
